// Rewind one enemy to a remembered position; forged elements remain attached to the strike.
const REWIND_ANCHOR_SIGNATURE=['巻戻しの楔',26,8,'敵1体の位置を記録し、2秒後に220%で攻撃。通常敵は記録地点へ戻し、構え中の攻撃を中断する。戻せる距離は400まで。壁・狭い足場・ボス・訓練標的は移動させず攻撃のみ。自分から対象が500を超えるか壁に隠れると解除。再発動で前の楔を置き換える。','M26 7V43M17 14H35M9 29Q9 43 26 43Q43 43 43 29M5 31L9 25L15 30M42 13Q28 0 13 13M13 7V13H19'];
SIGNATURE_SKILLS.push(REWIND_ANCHOR_SIGNATURE);Object.assign(GEM.crafted_3_1,{name:REWIND_ANCHOR_SIGNATURE[0],cost:26,cool:8,desc:REWIND_ANCHOR_SIGNATURE[3],ability:null,signature:89,tags:['spell']});
SIGNATURE_AUDIO.push(['rewindanchor',560,.35]);SKILL_AUDIO_FAMILIES.airy.add('rewindanchor');
const rewindAnchorCastBase=castCraftedSkill;castCraftedSkill=(build,...args)=>{let result=rewindAnchorCastBase(build,...args);if(GEM[build.type]?.signature!==89)return result;let s=signatureSpells.at(-1);if(s?.mode!==89)return result;signatureSpells=signatureSpells.filter(v=>v.mode!==89||v===s);if(!s.target){signatureSpells=signatureSpells.filter(v=>v!==s);say('照準の近くに敵がいません');return result;}s.owner=p;s.anchor={x:s.target.x,y:s.target.y};s.x=s.anchor.x;s.y=s.anchor.y;return result;};
const rewindAnchorStepBase=stepSignature;stepSignature=(s,dt)=>{if(s.mode!==89)return rewindAnchorStepBase(s,dt);if(dead||p.hp<=0||s.owner!==p)return false;if(paused||!Number.isFinite(dt)||dt<=0)return true;let e=s.target;if(!e||e.hp<=0||!enemies.includes(e)||dist(p,e)>500||!lineClear(p,e))return false;s.time=Math.round((s.time+dt)*1e6)/1e6;if(s.time<2)return true;
 if(!e.boss&&!e.dummy&&dist(e,s.anchor)<=400&&dist(p,s.anchor)<=500&&lineClear(e,s.anchor)&&lineClear(p,s.anchor)&&passable(s.anchor.x,s.anchor.y,enemyHitRadius(e))){let from={x:e.x,y:e.y};e.x=s.anchor.x;e.y=s.anchor.y;e.path=[];e.nav=0;e.attack=null;e.state='idle';e.elapsed=0;e.struck=true;e.t=Math.max(e.t||0,.65);burst(from.x,from.y,35,'#a9e8df');}
 spellHit(e,s.damage*2.2,s.build);burst(e.x,e.y,55,ELEMENTS[s.build.elements[0]].color);playSignatureAudio(89,true,e.x,e.y);return false;};
const rewindAnchorPaintBase=paintSignatureSpells;paintSignatureSpells=()=>{rewindAnchorPaintBase();for(let s of signatureSpells){if(s.mode!==89||s.owner!==p||!s.target||s.target.hp<=0)continue;let color=ELEMENTS[s.build.elements[0]].color;if(visibleAt(s.anchor.x,s.anchor.y)){groundRing(s.anchor.x,s.anchor.y,32,'#98e9dd',2);groundRing(s.anchor.x,s.anchor.y,38*Math.max(0,1-s.time/2),color,2);}if(visibleAt(s.target.x,s.target.y)){groundRing(s.target.x,s.target.y,24,color,1);if(visibleAt(s.anchor.x,s.anchor.y))paintLinkLine(s.anchor,s.target,'#98e9dd',1);}}};
const rewindAnchorStatusBase=controlSkillStatus;controlSkillStatus=s=>s.mode===89?{label:'巻戻し '+Math.max(0,2-s.time).toFixed(1)+'秒',value:Math.max(0,1-s.time/2),waiting:true}:rewindAnchorStatusBase(s);
